import * as React from "react";
import { cx } from "./cx";
import { Icon } from "./icon";

export interface InlineFormProps
  extends Omit<React.FormHTMLAttributes<HTMLFormElement>, "onSubmit"> {
  placeholder?: string;
  buttonLabel?: React.ReactNode;
  successLabel?: React.ReactNode;
  /** The action only appears once this returns true. Defaults to a loose e-mail check. */
  validate?: (value: string) => boolean;
  onSubmit?: (value: string) => void;
  inputProps?: React.InputHTMLAttributes<HTMLInputElement>;
}

/** One field, one action; the action sits inside the field. */
export function InlineForm({
  placeholder = "Your e-mail",
  buttonLabel = "Subscribe",
  successLabel = "You're on the list",
  validate = (v) => /.+@.+\..+/.test(v),
  onSubmit,
  className,
  inputProps,
  ...props
}: InlineFormProps) {
  const [value, setValue] = React.useState("");
  const [done, setDone] = React.useState(false);
  const valid = validate(value);

  if (done) {
    return (
      <div className="rs-subscribed">
        <Icon name="check" size={16} />
        {successLabel}
      </div>
    );
  }

  return (
    <form
      className={cx("rs-inline-field", className)}
      onSubmit={(e) => {
        e.preventDefault();
        if (!valid) return;
        onSubmit?.(value);
        setDone(true);
      }}
      {...props}
    >
      <input
        className="rs-inline-input"
        placeholder={placeholder}
        value={value}
        onChange={(e) => setValue(e.target.value)}
        {...inputProps}
      />
      <span className={cx("rs-reveal", valid && "rs-reveal-in")}>
        <button type="submit" className="rs-btn-primary rs-inline-btn" tabIndex={valid ? 0 : -1}>
          {buttonLabel}
        </button>
      </span>
    </form>
  );
}

import * as React from "react";
import { cx } from "./cx";

/**
 * Raster chrome marks. Vera 28 Aug 2026.
 *
 * 16×16 module, optical center 8,8. Stroke 1, currentColor, fill none.
 * Cap butt, join miter, no rx. Hairline stays 1 CSS px at 12 and 16.
 * Copied is check. Accordion down is chevron-right rotated 90°.
 */
export const ICON_STROKE = 1;
export const ICON_VIEWBOX = 16;

export const iconInk = {
  fill: "none",
  stroke: "currentColor",
  strokeWidth: ICON_STROKE,
  strokeLinecap: "butt",
  strokeLinejoin: "miter",
  vectorEffect: "non-scaling-stroke",
} as const;

export const iconNames = ["copy", "copied", "chevron-left", "chevron-right", "close"] as const;
export type IconName = (typeof iconNames)[number] | "check";
export type IconSize = 12 | 16;
export type IconRotate = 90 | 180 | 270;

const marks: Record<(typeof iconNames)[number], React.ReactNode> = {
  copy: (
    <>
      <path d="M6.5 2.5 H13.5 V9.5" {...iconInk} />
      <rect x="2.5" y="6.5" width="7" height="7" {...iconInk} />
    </>
  ),
  copied: <path d="M3.5 8.5 L6.5 11.5 L12.5 4.5" {...iconInk} />,
  "chevron-left": <path d="M10.5 3.5 L5.5 8 L10.5 12.5" {...iconInk} />,
  "chevron-right": <path d="M5.5 3.5 L10.5 8 L5.5 12.5" {...iconInk} />,
  close: (
    <>
      <path d="M4.5 4.5 L11.5 11.5" {...iconInk} />
      <path d="M11.5 4.5 L4.5 11.5" {...iconInk} />
    </>
  ),
};

function resolveName(name: IconName): (typeof iconNames)[number] {
  return name === "check" ? "copied" : name;
}

export interface IconProps extends Omit<React.SVGAttributes<SVGSVGElement>, "children" | "rotate"> {
  name: IconName;
  size?: IconSize;
  /** Same mark, spun around 8,8. Accordion down is chevron-right at 90. */
  rotate?: IconRotate;
}

/** One mark. Size is the drawn square; the viewBox is always 16. */
export function Icon({ name, size = 16, rotate, className, ...props }: IconProps) {
  const nodes = marks[resolveName(name)];
  return (
    <svg
      className={cx("rs-icon", className)}
      viewBox="0 0 16 16"
      width={size}
      height={size}
      aria-hidden="true"
      {...iconInk}
      {...props}
    >
      {rotate ? <g transform={`rotate(${rotate} 8 8)`}>{nodes}</g> : nodes}
    </svg>
  );
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Inline form: the action lives inside the field ── */
.rs-inline-field{display:flex;align-items:center;gap:8px;width:100%;border:1px solid var(--divider);border-radius:var(--radius-sm);background:var(--bg);padding:4px 6px 4px 12px;transition:border-color var(--duration-snap) var(--ease)}
.rs-inline-field:focus-within{border-color:var(--accent)}
.rs-inline-input{flex:1;min-width:0;border:none;background:none;font-family:inherit;font-size:14px;letter-spacing:-.01em;color:var(--text);outline:none;padding:7px 0}
.rs-inline-input::placeholder{color:var(--text-secondary)}
.rs-inline-btn{height:28px;padding:0 16px;font-size:12.5px;min-width:0;border-radius:var(--radius-sm);white-space:nowrap}
.rs-reveal{max-width:0;opacity:0;overflow:hidden;transition:max-width var(--duration) var(--ease),opacity var(--duration) var(--ease)}
.rs-reveal-in{max-width:160px;opacity:1}
.rs-subscribed{display:flex;align-items:center;gap:8px;font-size:14px;font-weight:600;letter-spacing:-.01em;color:var(--text);animation:rsConfirm var(--duration-confirm) var(--ease)}
@keyframes rsConfirm{from{opacity:0}to{opacity:1}}
